"""
记忆服务模块

提供记忆管理的业务逻辑，集成记忆检测器
"""

from typing import Optional, Tuple, List, Dict
from dataclasses import dataclass
import re

from storage import MemoryStore
from models import Memory, MemoryCreate, MemoryList, MemoryCategory, MemorySourceType
from config import (
    MemoryConfig,
    MEMORY_ADD_TRIGGERS,
    MEMORY_DELETE_TRIGGERS,
    MEMORY_LIST_TRIGGERS,
)


@dataclass
class DetectionResult:
    """记忆检测结果"""
    detected: bool
    content: Optional[str] = None
    category: Optional[str] = None
    confidence: float = 0.0
    source: str = "none"  # "rule", "llm", "hybrid"


class MemoryService:
    """
    记忆服务类

    提供记忆管理的高级接口，集成多种检测器
    """

    def __init__(self, user_id: str = "default_user"):
        """
        初始化记忆服务

        Args:
            user_id: 用户ID
        """
        self.user_id = user_id
        self.store = MemoryStore(user_id)

        # 延迟初始化检测器（避免循环导入）
        self._rule_detector = None
        self._llm_detector = None

    @property
    def rule_detector(self):
        """获取规则检测器（懒加载）"""
        if self._rule_detector is None:
            from llm.memory_detector import RuleBasedDetector
            self._rule_detector = RuleBasedDetector()
        return self._rule_detector

    @property
    def llm_detector(self):
        """获取LLM检测器（懒加载）"""
        if self._llm_detector is None:
            from llm.memory_detector import MemoryDetector
            self._llm_detector = MemoryDetector()
        return self._llm_detector

    # =========================================================================
    # 意图检测 - 显式记忆命令
    # =========================================================================

    def detect_memory_intent(self, message: str) -> Tuple[str, Optional[str]]:
        """
        检测消息中的显式记忆操作意图

        这个方法检测用户的直接记忆命令，如"记住xxx"、"忘记xxx"

        Args:
            message: 用户消息

        Returns:
            (intent_type, content) 元组
            intent_type: "add", "delete", "list", "none"
            content: 提取的内容（用于add/delete）
        """
        message_lower = message.lower()

        # 检测列出记忆意图
        for trigger in MEMORY_LIST_TRIGGERS:
            if trigger.lower() in message_lower:
                return ("list", None)

        # 检测添加记忆意图
        for trigger in MEMORY_ADD_TRIGGERS:
            if trigger.lower() in message_lower:
                content = self._extract_memory_content(message, trigger)
                if content:
                    return ("add", content)

        # 检测删除记忆意图
        for trigger in MEMORY_DELETE_TRIGGERS:
            if trigger.lower() in message_lower:
                content = self._extract_delete_target(message, trigger)
                if content:
                    return ("delete", content)

        return ("none", None)

    def _extract_memory_content(self, message: str, trigger: str) -> Optional[str]:
        """从消息中提取要记忆的内容"""
        content = message

        for t in MEMORY_ADD_TRIGGERS:
            content = re.sub(rf'\b{re.escape(t)}\b', '', content, flags=re.IGNORECASE)

        content = content.strip()
        content = re.sub(r'^(that|this|:|\s)+', '', content, flags=re.IGNORECASE)
        content = re.sub(r'^(的是|是|：|\s)+', '', content)

        return content.strip() if content.strip() else None

    def _extract_delete_target(self, message: str, trigger: str) -> Optional[str]:
        """从消息中提取要删除的目标"""
        content = message

        for t in MEMORY_DELETE_TRIGGERS:
            content = re.sub(rf'\b{re.escape(t)}\b', '', content, flags=re.IGNORECASE)

        content = content.strip()
        content = re.sub(r'^(about|关于|的|：|:|\s)+', '', content, flags=re.IGNORECASE)

        return content.strip() if content.strip() else None

    # =========================================================================
    # 智能记忆检测 - 从普通对话中检测可记忆信息
    # =========================================================================

    def detect_memorable_info(
        self,
        message: str,
        mode: Optional[str] = None,
    ) -> DetectionResult:
        """
        从普通对话中检测可记忆的信息

        这个方法用于自动检测用户消息中包含的个人信息，
        即使用户没有显式说"记住xxx"

        Args:
            message: 用户消息
            mode: 检测模式 ("rule", "llm", "hybrid")，默认使用配置

        Returns:
            DetectionResult 检测结果
        """
        mode = mode or MemoryConfig.DETECTION_MODE

        if mode == "rule":
            return self._detect_with_rules(message)
        elif mode == "llm":
            return self._detect_with_llm(message)
        else:  # hybrid
            return self._detect_hybrid(message)

    def _detect_with_rules(self, message: str) -> DetectionResult:
        """使用规则检测器"""
        result = self.rule_detector.detect(message)

        if result and result.get("should_remember"):
            return DetectionResult(
                detected=True,
                content=result.get("content"),
                category=result.get("category", "misc"),
                confidence=0.8,  # 规则匹配的固定置信度
                source="rule",
            )

        return DetectionResult(detected=False)

    def _detect_with_llm(self, message: str) -> DetectionResult:
        """使用LLM检测器"""
        result = self.llm_detector.detect(message)

        if result and result.get("should_remember"):
            return DetectionResult(
                detected=True,
                content=result.get("content"),
                category=result.get("category", "misc"),
                confidence=result.get("confidence", 0.8),
                source="llm",
            )

        return DetectionResult(detected=False)

    def _detect_hybrid(self, message: str) -> DetectionResult:
        """
        混合检测模式

        1. 先用规则快速检测
        2. 如果规则检测到，直接返回
        3. 如果规则没检测到，但消息可能包含个人信息，使用LLM检测
        """
        # 先尝试规则检测（快速）
        rule_result = self._detect_with_rules(message)
        if rule_result.detected:
            return rule_result

        # 判断是否需要LLM检测（避免每条消息都调用LLM）
        if self._should_try_llm_detection(message):
            llm_result = self._detect_with_llm(message)
            if llm_result.detected:
                llm_result.source = "hybrid"
                return llm_result

        return DetectionResult(detected=False)

    def _should_try_llm_detection(self, message: str) -> bool:
        """
        判断是否应该尝试LLM检测

        为了避免每条消息都调用LLM，这里使用简单规则预过滤
        """
        # 消息太短，不太可能包含有价值的信息
        if len(message) < 10:
            return False

        # 检查是否包含可能表示个人信息的词
        indicators = [
            "我", "my", "i ", "i'm", "i am",
            "喜欢", "讨厌", "想", "希望", "计划",
            "工作", "学习", "住", "来自",
            "名字", "叫", "是",
        ]

        message_lower = message.lower()
        for indicator in indicators:
            if indicator in message_lower:
                return True

        return False

    def auto_detect_and_save(
        self,
        message: str,
        conversation_id: Optional[str] = None,
        require_confirmation: bool = True,
    ) -> Tuple[bool, Optional[str], Optional[Memory]]:
        """
        自动检测并保存记忆

        用于从普通对话中自动提取并存储用户信息

        Args:
            message: 用户消息
            conversation_id: 会话ID
            require_confirmation: 是否需要用户确认（当前未实现）

        Returns:
            (detected, confirmation_message, memory) 元组
        """
        if not MemoryConfig.AUTO_DETECT_ENABLED:
            return (False, None, None)

        # 检测可记忆信息
        result = self.detect_memorable_info(message)

        if not result.detected:
            return (False, None, None)

        # 检查置信度阈值
        if result.confidence < MemoryConfig.AUTO_DETECT_CONFIDENCE_THRESHOLD:
            return (False, None, None)

        # 保存记忆
        success, msg, memory = self.add_memory(
            content=result.content,
            category=result.category or "misc",
            source_type="detected",
            conversation_id=conversation_id,
        )

        if success:
            confirmation = f"💡 我注意到你提到了：「{result.content}」，已自动记住。"
            return (True, confirmation, memory)

        return (False, None, None)

    # =========================================================================
    # 记忆操作 CRUD
    # =========================================================================

    def add_memory(
        self,
        content: str,
        category: str = "misc",
        source_type: str = "explicit",
        conversation_id: Optional[str] = None,
    ) -> Tuple[bool, str, Optional[Memory]]:
        """
        添加记忆

        Args:
            content: 记忆内容
            category: 分类
            source_type: 来源类型 ("explicit", "detected", "imported")
            conversation_id: 来源会话ID

        Returns:
            (success, message, memory) 元组
        """
        # 检查长度限制
        if len(content) > MemoryConfig.MAX_MEMORY_LENGTH:
            return (False, f"记忆内容过长，最大{MemoryConfig.MAX_MEMORY_LENGTH}字符", None)

        # 检查数量限制
        if self.store.count() >= MemoryConfig.MAX_MEMORIES_PER_USER:
            return (False, f"记忆数量已达上限（{MemoryConfig.MAX_MEMORIES_PER_USER}条）", None)

        # 检查重复
        if self.store.check_duplicate(content):
            return (False, "该记忆已存在", None)

        # 解析分类
        try:
            cat = MemoryCategory(category)
        except ValueError:
            cat = MemoryCategory.MISC

        # 解析来源类型
        try:
            src_type = MemorySourceType(source_type)
        except ValueError:
            src_type = MemorySourceType.EXPLICIT

        # 创建记忆
        memory_create = MemoryCreate(
            content=content,
            category=cat,
            source_type=src_type,
            source_conversation_id=conversation_id,
        )

        memory = self.store.add(memory_create)

        return (True, "记忆已保存", memory)

    def delete_memory(self, memory_id: str) -> Tuple[bool, str]:
        """删除记忆"""
        if self.store.delete(memory_id):
            return (True, "记忆已删除")
        return (False, "未找到该记忆")

    def delete_memory_by_keyword(self, keyword: str) -> Tuple[bool, str, int]:
        """根据关键词删除记忆"""
        count = self.store.delete_by_content(keyword)
        if count > 0:
            return (True, f"已删除{count}条相关记忆", count)
        return (False, "未找到相关记忆", 0)

    def list_memories(self, category: Optional[str] = None) -> MemoryList:
        """列出记忆"""
        return self.store.list_all(category=category)

    def search_memories(self, query: str) -> MemoryList:
        """搜索记忆"""
        return self.store.search(query)

    def get_memory_context(self) -> str:
        """获取记忆上下文（用于注入到LLM）"""
        memory_list = self.store.list_all()
        return memory_list.to_context_block()

    def format_memory_list_response(self) -> str:
        """格式化记忆列表响应（用于回复用户查询）"""
        memory_list = self.store.list_all()

        if memory_list.total == 0:
            return "我目前还没有记住关于你的任何信息。你可以告诉我一些你希望我记住的事情。"

        # 按分类分组
        grouped = {}
        for memory in memory_list.memories:
            cat = memory.category
            if cat not in grouped:
                grouped[cat] = []
            grouped[cat].append(memory)

        lines = [f"我记住了关于你的 {memory_list.total} 条信息：\n"]

        category_names = {
            MemoryCategory.IDENTITY: "👤 身份信息",
            MemoryCategory.PREFERENCE: "⚙️ 偏好设置",
            MemoryCategory.GOAL: "🎯 目标计划",
            MemoryCategory.BACKGROUND: "📚 背景经历",
            MemoryCategory.PROJECT: "🔧 项目信息",
            MemoryCategory.MISC: "📝 其他",
        }

        category_order = [
            MemoryCategory.IDENTITY,
            MemoryCategory.PREFERENCE,
            MemoryCategory.GOAL,
            MemoryCategory.BACKGROUND,
            MemoryCategory.PROJECT,
            MemoryCategory.MISC,
        ]

        for cat in category_order:
            if cat in grouped:
                lines.append(f"\n**{category_names[cat]}**")
                for memory in grouped[cat]:
                    source_tag = " 🔍" if memory.source_type == MemorySourceType.DETECTED else ""
                    lines.append(f"- {memory.content}{source_tag}")

        lines.append("\n\n你可以告诉我「忘记关于xxx的信息」来删除任何记忆。")
        lines.append("（🔍 标记表示自动检测到的记忆）")

        return "\n".join(lines)

    # =========================================================================
    # 智能分类
    # =========================================================================

    def auto_categorize(self, content: str) -> MemoryCategory:
        """自动分类记忆内容"""
        content_lower = content.lower()

        identity_keywords = [
            "我叫", "我是", "我的名字", "my name", "i am", "i'm",
            "岁", "年龄", "住在", "来自", "在工作", "职业",
        ]

        preference_keywords = [
            "喜欢", "偏好", "习惯", "prefer", "like", "favorite",
            "不喜欢", "讨厌", "hate", "don't like",
        ]

        goal_keywords = [
            "想要", "计划", "目标", "打算", "希望",
            "want to", "plan to", "goal", "going to",
        ]

        background_keywords = [
            "毕业", "学过", "曾经", "以前", "经历",
            "studied", "graduated", "used to", "experience",
        ]

        project_keywords = [
            "项目", "开发", "做", "building", "working on",
            "正在做", "在做", "project",
        ]

        for keyword in identity_keywords:
            if keyword in content_lower:
                return MemoryCategory.IDENTITY

        for keyword in preference_keywords:
            if keyword in content_lower:
                return MemoryCategory.PREFERENCE

        for keyword in goal_keywords:
            if keyword in content_lower:
                return MemoryCategory.GOAL

        for keyword in background_keywords:
            if keyword in content_lower:
                return MemoryCategory.BACKGROUND

        for keyword in project_keywords:
            if keyword in content_lower:
                return MemoryCategory.PROJECT

        return MemoryCategory.MISC

    def smart_add_memory(
        self,
        content: str,
        conversation_id: Optional[str] = None,
    ) -> Tuple[bool, str, Optional[Memory]]:
        """智能添加记忆（自动分类）"""
        category = self.auto_categorize(content)
        return self.add_memory(
            content=content,
            category=category.value,
            source_type="explicit",
            conversation_id=conversation_id,
        )

    # =========================================================================
    # 批量操作
    # =========================================================================

    def process_message_for_memories(
        self,
        message: str,
        conversation_id: Optional[str] = None,
    ) -> Dict:
        """
        完整处理消息中的记忆相关操作

        这是一个综合方法，同时处理：
        1. 显式记忆命令（记住/忘记/列出）
        2. 自动记忆检测

        Args:
            message: 用户消息
            conversation_id: 会话ID

        Returns:
            处理结果字典
        """
        result = {
            "intent": "none",
            "action_taken": False,
            "response": None,
            "memory": None,
            "auto_detected": False,
        }

        # 1. 检测显式意图
        intent, content = self.detect_memory_intent(message)
        result["intent"] = intent

        if intent == "list":
            result["action_taken"] = True
            result["response"] = self.format_memory_list_response()
            return result

        if intent == "add" and content:
            success, msg, memory = self.smart_add_memory(content, conversation_id)
            result["action_taken"] = True
            result["memory"] = memory
            if success:
                result["response"] = f"好的，我记住了：{content}\n\n还有什么我可以帮你的吗？"
            else:
                result["response"] = f"抱歉，{msg}"
            return result

        if intent == "delete" and content:
            success, msg, count = self.delete_memory_by_keyword(content)
            result["action_taken"] = True
            if success:
                result["response"] = f"好的，我已经删除了关于「{content}」的记忆。"
            else:
                result["response"] = f"我没有找到关于「{content}」的记忆。你可以说「你记得什么」来查看我记住的所有信息。"
            return result

        # 2. 如果没有显式命令，尝试自动检测（不影响正常对话流程）
        if MemoryConfig.AUTO_DETECT_ENABLED:
            detected, confirmation, memory = self.auto_detect_and_save(
                message, conversation_id
            )
            if detected:
                result["auto_detected"] = True
                result["memory"] = memory
                # 注意：自动检测不设置response，让正常对话继续
                # confirmation会作为补充信息在对话后显示
                result["auto_detect_confirmation"] = confirmation

        return result

